#!/usr/bin/env bash
# Mount the small facts MCP connector on the running workbench.
#
# It exists to prove the connector path end to end: a mission reaches a real MCP
# tool through a mounted server and the brief quotes its answer. The external
# connectors (Attio, Qonto, ...) take the same shape with their own command, args
# and environment; they only need their credentials.
#
# The connector is mounted like every other one, through mount-connector.sh: a
# descriptor in <live>/connectors, the composition regenerated by the renderer
# through the shared guard (patchfile.py). The patch file is never edited here:
# a hand-appended block after the `[]` dsh writes stops the workbench.
#   enable-facts-connector.sh [tools archive] [mount-connector.sh options, e.g. --no-restart]
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
LIVE=${MNDT_HOME:-/data/mndt/live}
TOOLS="$LIVE/tools"
SRC=/root/mndt-tools.tar.gz
if [ $# -gt 0 ] && [ "${1#--}" = "$1" ]; then SRC=$1; shift; fi

mkdir -p "$TOOLS" "$LIVE/connectors"
if [ -f "$SRC" ]; then
  tar -xzf "$SRC" -C "$TOOLS"
fi
[ -f "$TOOLS/facts-mcp.mjs" ] || { echo "missing $TOOLS/facts-mcp.mjs" >&2; exit 1; }

exec bash "$here/mount-connector.sh" workbench_facts node /opt/mndt-tools/facts-mcp.mjs "$@"
